export const getCompareRunsUrl = (params: CompareRunsParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/compare?${stringifiedParams}` : `/api/compare`
}

export const compareRuns = async (params: CompareRunsParams, options?: Parameters<typeof customFetch>[1]): Promise<Comparison> => {

  return customFetch<Comparison>(getCompareRunsUrl(params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getCompareRunsQueryKey = (params?: CompareRunsParams,) => {
    return [
    `/api/compare`, ...(params ? [params] : [])
    ] as const;
    }


export const getCompareRunsQueryOptions = <TData = Awaited<ReturnType<typeof compareRuns>>, TError = ErrorType<unknown>>(params: CompareRunsParams, options?: { query?:Partial<UseQueryOptions<Awaited<ReturnType<typeof compareRuns>>, TError, TData>>, request?: SecondParameter<typeof customFetch>}
) => {

const {query: queryOptions, request: requestOptions} = options ?? {};

  const queryKey =  queryOptions?.queryKey ?? getCompareRunsQueryKey(params);



    const queryFn: QueryFunction<Awaited<ReturnType<typeof compareRuns>>> = ({ signal }) => compareRuns(params, { signal, ...requestOptions });





   return  { queryKey, queryFn, ...queryOptions} as UseQueryOptions<Awaited<ReturnType<typeof compareRuns>>, TError, TData> & { queryKey: DataTag<QueryKey, TData, TError> }
}

